<section class="page-head"><div><div class="kicker"><i class="fa-solid fa-link"></i> Acquisition channels</div><h1>Candidate sources</h1><p>Add and track where resumes enter the recruiter pipeline.</p></div></section><section class="source-grid"><form class="panel source-form" method="post"><h2>Add a source</h2><?php if($message):?><div class="success"><i class="fa-solid fa-circle-check"></i> <?=$message?></div><?php endif?><input type="hidden" name="csrf" value="<?=$_SESSION['csrf']?>"><div class="field"><label>Source name</label><input class="control" name="name" required placeholder="LinkedIn campaign"></div><div class="field"><label>Type</label><select class="control" name="type"><option>Job board</option><option>Referral</option><option>Agency</option><option>Career page</option><option>Event</option><option>Other</option></select></div><div class="field"><label>URL (optional)</label><input class="control" type="url" name="url" placeholder="https://"></div><button class="btn btn-primary"><i class="fa-solid fa-plus"></i>Add source</button></form><article class="panel source-list"><h2>Active sources</h2><?php if(!$sources):?><div class="empty">No sources added yet.</div><?php endif?><?php foreach(array_reverse($sources) as $s):?><div class="source-item"><span class="source-icon"><i class="fa-solid fa-link"></i></span><div class="source-copy"><strong><?=htmlspecialchars($s['name'])?></strong><span><?=htmlspecialchars($s['type'])?> · Added <?=htmlspecialchars(substr($s['created_at'],0,10))?></span></div><?php if($s['url']):?><a class="source-link" href="<?=htmlspecialchars($s['url'])?>" target="_blank" rel="noopener">Open <i class="fa-solid fa-arrow-up-right-from-square"></i></a><?php endif?></div><?php endforeach?></article></section>
